mapper.select:
SELECT distinct I.ITEM_ID, I.ITEM_USER_CODE, I.ITEM_NAME, I.ITEM_SUMMARY, I.ITEM_IMAGE, I.SALE_PRICE, I.STOCK_QUANTITY, I.STOCK_FLAG, I.SHIPMENT_RETURN_ID, I.ITEM_OPTION_FLAG, I.ITEM_OPTION_TYPE, I.ITEM_OPTION_TITLE1, I.ITEM_OPTION_TITLE2, I.ITEM_OPTION_TITLE3, IC.ITEM_CATEGORY_ID, IC.CATEGORY_ID, IC.ORDERING AS CATEGORY_ORDERING, crypto_dec('normal', SR.ZIPCODE, '', 0) AS RETURN_ZIPCODE, crypto_dec('normal', SR.ADDRESS, '', 0) AS RETURN_ADDRESS, crypto_dec('normal', SR.ADDRESS_DETAIL, '', 0) AS RETURN_ADDRESS_DETAIL, crypto_dec('normal', SR.NAME, '', 0) AS RETURN_NAME, crypto_dec('normal', SR.TELEPHONE_NUMBER, '', 0) AS RETURN_TELEPHONE_NUMBER, IO.ITEM_OPTION_ID AS ITEM_OPTION_ID, IO.OPTION_NAME1 AS OPTION_NAME1, IO.OPTION_NAME2 AS OPTION_NAME2, IO.OPTION_NAME3 AS OPTION_NAME3 FROM OP_ITEM I INNER JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID INNER JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID AND C.CATEGORY_FLAG = 'Y' LEFT JOIN OP_ITEM_OPTION IO ON I.ITEM_ID = IO.ITEM_ID LEFT JOIN OP_SHIPMENT_RETURN SR on I.SHIPMENT_RETURN_ID = SR.SHIPMENT_RETURN_ID WHERE I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_ID IN
#{code}
ORDER BY IC.ORDERING ASC
